# side paths are explained in separate actions with guards, preserving direction.
d.line([(150,200),(30,200),(30,118),(95,118)],'[changes: RQ-01]',labelpos=(115,157))
d.line([(370,200),(425,200),(425,105),(435,105)],'[reject]',labelpos=(467,184));b(d,435,75,'RQ-08 Rejected\nReason and notify',w=150,h=60);d.line([(510,135),(510,155)]);d.dot(510,165,True)
d.line([(150,383),(30,383),(30,294),(95,294)],'[no: search again]',labelpos=(119,340))
d.line([(370,645),(488,645),(488,300),(425,300)],'[decline/conflict]',labelpos=(496,560))
d.box(605,790,490,145,'Exception paths\nAny transfer rejection: TR-08; reason and release units.\nPre-handover cancellation: TR-09; reason and release.\nHold expires before approval: release; return to search.\nTR-07 dispute: no owner change; resolve to receipt\nor return and cancel with released quantity.\nAI down or confidence < 0.50: classic search.',fill='#fff6e3',size=15)
